<?php
declare(strict_types=1);
namespace PYH\Tests\Workflow;
use DomainException;use PDO;use PHPUnit\Framework\TestCase;use PYH\Application\AuditService;use PYH\Application\ProposalService;use PYH\Application\QuoteService;use PYH\Application\SearchService;use PYH\Database\ConnectionFactory;use PYH\Database\TestDatabasePolicy;use PYH\Domain\Quote\QuoteStatus;use PYH\Security\Actor;use PYH\Security\Password;use PYH\Security\PermissionEvaluator;use RuntimeException;
final class QuoteEngineWorkflowTest extends TestCase{
 private PDO $pdo;private Actor $actor;private QuoteService $quotes;private ProposalService $proposals;private int $customer;private int $traveller;private int $enquiry;
 protected function setUp():void{$database=getenv('TEST_DB_DATABASE');$environment=getenv('APP_ENV');$host=getenv('TEST_DB_HOST')?:'127.0.0.1';if(!is_string($database)||!is_string($environment)){self::markTestSkipped('Phase 3 database is not configured.');}TestDatabasePolicy::assertDisposable($environment,$host,$database);$this->pdo=ConnectionFactory::create(['host'=>$host,'port'=>(int)(getenv('TEST_DB_PORT')?:3306),'database'=>$database,'username'=>getenv('TEST_DB_USERNAME')?:'','password'=>getenv('TEST_DB_PASSWORD')?:'','charset'=>'utf8mb4']);$this->clear();$this->seed();$audit=new AuditService($this->pdo,'test');$this->quotes=new QuoteService($this->pdo,new PermissionEvaluator(),$audit);$this->proposals=new ProposalService($this->pdo,new PermissionEvaluator(),$audit,$this->quotes);}
 public function testPackageRevisionDecisionAndImmutableBookingHandoff():void{$id=$this->baseQuote('Package Holiday');$this->quotes->attachTraveller($this->actor,$id,$this->traveller,'Adult',true);$flight=$this->quotes->addComponent($this->actor,$id,['component_type'=>'Flight','title'=>'Return flights','supplier'=>'Example Air','origin'=>'LHR','destination'=>'FNC','selling_price'=>'600.10']);$this->quotes->addFlightSector($this->actor,$id,$flight,['journey_direction'=>'Outbound','airline'=>'Example Air','departure_airport'=>'LHR','arrival_airport'=>'FNC','departure_at_utc'=>'2027-06-01 08:00:00','arrival_at_utc'=>'2027-06-01 12:00:00']);$this->quotes->addComponent($this->actor,$id,['component_type'=>'Accommodation','title'=>'Ocean Hotel','supplier'=>'Beds Ltd','selling_price'=>'1200.20','property_name'=>'Ocean Hotel','check_in_date'=>'2027-06-01','check_out_date'=>'2027-06-08','nights'=>7]);$this->quotes->addComponent($this->actor,$id,['component_type'=>'Transfer','title'=>'Airport transfer','supplier'=>'Transfer Ltd','selling_price'=>'100.00']);$this->quotes->addComponent($this->actor,$id,['component_type'=>'Attraction','title'=>'Island tour','inclusion_state'=>'Optional','selling_price'=>'50.00']);$this->quotes->addAdjustment($this->actor,$id,'Fee','10.00','Booking fee','Customer');self::assertSame('1910.30',$this->quotes->quote($this->actor,$id)['customer_total']);self::assertSame('50.00',$this->quotes->quote($this->actor,$id)['optional_total']);$this->passCompliance($id);$this->quotes->transition($this->actor,$id,QuoteStatus::Ready);self::assertSame('Quoted',$this->scalar("SELECT status FROM enquiries WHERE id={$this->enquiry}"));$v1=$this->proposals->generate($this->actor,$id);$this->proposals->recordSent($this->actor,$id,$v1,'Email','jane@example.test');$v1Hash=$this->scalar("SELECT snapshot_sha256 FROM proposal_versions WHERE id={$v1}");$this->quotes->createRevision($this->actor,$id);$this->quotes->addAdjustment($this->actor,$id,'Discount','10.00','Goodwill','Customer');$this->passCompliance($id);$this->quotes->transition($this->actor,$id,QuoteStatus::Ready);$v2=$this->proposals->generate($this->actor,$id);$this->proposals->recordSent($this->actor,$id,$v2,'In Person',null);self::assertSame($v1Hash,$this->scalar("SELECT snapshot_sha256 FROM proposal_versions WHERE id={$v1}"));$this->proposals->recordDecision($this->actor,$id,$v2,QuoteStatus::Accepted,'Customer','Signed acceptance');$handoff=$this->proposals->bookingHandoff($this->actor,$id);self::assertGreaterThan(0,$handoff);self::assertSame('Ready',$this->scalar("SELECT readiness_status FROM quote_booking_handoffs WHERE id={$handoff}"));self::assertSame(2,(int)$this->scalar("SELECT version_number FROM proposal_versions WHERE id={$v2}"));}
 public function testCruiseAndCruiseStayStructuredChronologicalWorkflows():void{$cruise=$this->baseQuote('Cruise');$this->quotes->attachTraveller($this->actor,$cruise,$this->traveller,'Adult',true);$component=$this->quotes->addComponent($this->actor,$cruise,['component_type'=>'Cruise','title'=>'Mediterranean cruise','supplier'=>'Cruise Line','selling_price'=>'2200.00','cruise_line'=>'Example Cruises','ship'=>'Example Star','sailing_date'=>'2027-06-01','duration_nights'=>7,'embarkation_port'=>'Barcelona','disembarkation_port'=>'Barcelona']);self::assertSame('Example Star',$this->scalar("SELECT ship FROM quote_cruise_details WHERE component_id={$component}"));$this->passCompliance($cruise);$this->quotes->transition($this->actor,$cruise,QuoteStatus::Ready);$p=$this->proposals->generate($this->actor,$cruise);$this->proposals->recordSent($this->actor,$cruise,$p,'Customer Portal',null);$this->proposals->recordDecision($this->actor,$cruise,$p,QuoteStatus::Declined,'Customer','Changed plans');self::assertSame('Declined',$this->quotes->quote($this->actor,$cruise)['status']);
  $stay=$this->baseQuote('Cruise & Stay');$this->quotes->attachTraveller($this->actor,$stay,$this->traveller,'Adult',true);foreach([['Flight','Outbound flight','2027-06-01 08:00:00'],['Accommodation','Pre-cruise hotel','2027-06-01 14:00:00'],['Cruise','Cruise','2027-06-03 10:00:00'],['Accommodation','Post-cruise hotel','2027-06-10 14:00:00'],['Flight','Inbound flight','2027-06-12 12:00:00']] as $i=>$row){$data=['component_type'=>$row[0],'title'=>$row[1],'start_at_utc'=>$row[2],'supplier'=>'Supplier','selling_price'=>'100.00'];if($row[0]==='Accommodation'){$data+=['property_name'=>$row[1],'check_in_date'=>substr($row[2],0,10),'check_out_date'=>date('Y-m-d',strtotime(substr($row[2],0,10).' +2 days')),'nights'=>2];}if($row[0]==='Cruise'){$data+=['cruise_line'=>'Line','ship'=>'Ship','sailing_date'=>'2027-06-03','duration_nights'=>7,'embarkation_port'=>'Port A','disembarkation_port'=>'Port B'];}$this->quotes->addComponent($this->actor,$stay,$data);}$this->passCompliance($stay);$this->quotes->transition($this->actor,$stay,QuoteStatus::Ready);$proposal=$this->proposals->generate($this->actor,$stay);$json=(string)$this->scalar("SELECT snapshot FROM proposal_versions WHERE id={$proposal}");self::assertLessThan(strpos($json,'Post-cruise'),strpos($json,'Pre-cruise'));}
 public function testMultiCentreOptionalAndExpiryEvidence():void{$id=$this->baseQuote('Tailor-Made');$this->quotes->attachTraveller($this->actor,$id,$this->traveller,'Adult',true);foreach(['Hotel A','Hotel B'] as $name){$this->quotes->addComponent($this->actor,$id,['component_type'=>'Accommodation','title'=>$name,'supplier'=>'Beds','selling_price'=>'500.00','property_name'=>$name,'check_in_date'=>'2027-06-01','check_out_date'=>'2027-06-03','nights'=>2]);}$this->quotes->addComponent($this->actor,$id,['component_type'=>'Lounge','title'=>'Airport lounge','inclusion_state'=>'Optional','selling_price'=>'30.00']);self::assertSame('1000.00',$this->quotes->quote($this->actor,$id)['customer_total']);$this->passCompliance($id);$this->quotes->transition($this->actor,$id,QuoteStatus::Ready);$p=$this->proposals->generate($this->actor,$id);$this->proposals->recordSent($this->actor,$id,$p,'Other',null);$this->proposals->recordDecision($this->actor,$id,$p,QuoteStatus::Expired,'System');self::assertSame(1,(int)$this->scalar("SELECT COUNT(*) FROM proposal_versions WHERE id={$p}"));self::assertSame('Expired',$this->quotes->quote($this->actor,$id)['status']);}
 public function testQuoteScopePermissionSearchAndPriceTamperingBoundaries():void{$id=$this->baseQuote('Package Holiday');$other=new Actor($this->actor->userId+999,$this->actor->organisationId,$this->actor->locationId,['quotes.view','scope.own'],true);try{$this->quotes->quote($other,$id);self::fail('Cross-agent IDOR was allowed.');}catch(RuntimeException $e){self::assertSame('Record not found.',$e->getMessage());}$crossOrg=new Actor($this->actor->userId,$this->actor->organisationId+999,$this->actor->locationId,['quotes.view','scope.organisation'],true);$this->expectRuntimeFailure(fn()=>$this->quotes->quote($crossOrg,$id));$inactive=new Actor($this->actor->userId,$this->actor->organisationId,$this->actor->locationId,['quotes.view','scope.organisation'],false);$this->expectRuntimeFailure(fn()=>$this->quotes->quote($inactive,$id));self::assertSame([],(new SearchService($this->pdo,new PermissionEvaluator()))->search($other,'Package'));try{$this->quotes->addComponent($this->actor,$id,['component_type'=>'Other','title'=>'Tampered','selling_price'=>'-1.00']);self::fail('Negative price tampering was allowed.');}catch(DomainException $e){self::assertStringContainsString('negative',$e->getMessage());}}
 private function baseQuote(string $type):int{return$this->quotes->create($this->actor,['customer_id'=>$this->customer,'enquiry_id'=>$this->enquiry,'product_type'=>$type,'title'=>$type.' proposal','departure_date'=>'2027-06-01','return_date'=>'2027-06-08','expires_at_utc'=>'2027-05-01 12:00:00']);}
 private function passCompliance(int $id):void{$e=array_fill_keys(['total_price_clear','mandatory_charges_included','material_information_present','supplier_identity_present','deposit_balance_clear','significant_terms_present','availability_caveat_present'],true);self::assertSame('Pass',$this->quotes->reviewCompliance($this->actor,$id,$e));}
 private function seed():void{$this->pdo->exec("INSERT INTO organisations (legal_name,trading_name) VALUES ('PYH Ltd','PYH')");$org=(int)$this->pdo->lastInsertId();$this->pdo->exec("INSERT INTO locations (organisation_id,name,internal_code) VALUES ({$org},'HQ','HQ')");$loc=(int)$this->pdo->lastInsertId();$hash=$this->pdo->quote(Password::hash('safe-password-123'));$this->pdo->exec("INSERT INTO users (organisation_id,location_id,first_name,last_name,email,password_hash,agent_code) VALUES ({$org},{$loc},'Alex','Agent','alex@example.test',{$hash},'A1')");$user=(int)$this->pdo->lastInsertId();$statement=$this->pdo->query('SELECT permission_key FROM permissions');self::assertNotFalse($statement);$permissions=array_values(array_map('strval',$statement->fetchAll(PDO::FETCH_COLUMN)));$this->actor=new Actor($user,$org,$loc,$permissions,true);$this->pdo->exec("INSERT INTO customers (organisation_id,owning_location_id,owning_agent_id,first_name,last_name,email,created_by_user_id,updated_by_user_id) VALUES ({$org},{$loc},{$user},'Jane','Doe','jane@example.test',{$user},{$user})");$this->customer=(int)$this->pdo->lastInsertId();$this->pdo->exec("INSERT INTO travellers (customer_id,first_name,last_name,date_of_birth) VALUES ({$this->customer},'Jane','Doe','1980-01-01')");$this->traveller=(int)$this->pdo->lastInsertId();$this->pdo->exec("INSERT INTO enquiries (reference,organisation_id,customer_id,assigned_location_id,assigned_agent_id,status,product_type,destinations,created_by_user_id,updated_by_user_id) VALUES ('PYH-E-TEST',{$org},{$this->customer},{$loc},{$user},'Contacted','Package Holiday',JSON_ARRAY('Madeira'),{$user},{$user})");$this->enquiry=(int)$this->pdo->lastInsertId();}
 private function clear():void{foreach(['quote_booking_handoffs','quote_decisions','proposal_deliveries','proposal_versions','quote_compliance_reviews','quote_adjustments','quote_flight_sectors','quote_accommodation_details','quote_cruise_details','quote_travellers','quote_components','quotes','audit_events','communications','tasks','enquiry_assignment_history','enquiries','travellers','customers','consultant_profiles','user_roles'] as $t){$this->pdo->exec("DELETE FROM {$t}");}$this->pdo->exec('DELETE rp FROM role_permissions rp JOIN roles r ON r.id=rp.role_id WHERE r.organisation_id IS NOT NULL');$this->pdo->exec('DELETE FROM roles WHERE organisation_id IS NOT NULL');foreach(['users','locations','organisations'] as $t){$this->pdo->exec("DELETE FROM {$t}");}}
 private function scalar(string $sql):mixed{$s=$this->pdo->query($sql);self::assertNotFalse($s);return$s->fetchColumn();}
 /** @param callable():mixed $operation */ private function expectRuntimeFailure(callable $operation):void{try{$operation();self::fail('Access was allowed.');}catch(RuntimeException){self::addToAssertionCount(1);}}
}
